"""Make the example laps (and the animated replay) that are published with the project.

Everything here is the project's own work, so it may be shared:
  * circuits generated by the project's own track generator (never Assetto Corsa tracks);
  * car files built from public data (``vehicles/library``);
  * drivers trained by the project.

Writes ``docs/laps/...`` (lap files, replayable in the web interface, Laps tab)
and ``docs/img/lap_replay.gif`` (shown in the README).

    python scripts/make_example_laps.py
"""

from __future__ import annotations

import json
import math
import sys
import tempfile
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from mv.envs.racing_env import EnvConfig  # noqa: E402
from mv.laps import EXAMPLE_DIR, laps_from_result, reference_lap_file, save_lap  # noqa: E402
from mv.planning.reference import reference_lap  # noqa: E402
from mv.rl.evaluate import evaluate  # noqa: E402
from mv.rl.ppo import load_policy  # noqa: E402
from mv.track.segments import segment_track  # noqa: E402
from mv.vehicle.params import find_vehicle, load_vehicle  # noqa: E402

EXAMPLES = [
    # (example name, car file, driver checkpoint, generator preset, track seed)
    # Road cars: added once a multi-car driver handles the public-data car files (engineering log WP25).
    ("mv_fs_example_1", "fs_generic_ev", "runs/fs_v1/best.pt", "fs_segments", 3),
    ("mv_fs_example_2", "fs_generic_ev", "runs/fs_v1/best.pt", "fs_segments", 7),
]


def env_cfg_of(ckpt: Path) -> EnvConfig:
    raw = json.loads((ckpt.parent / "config.json").read_text())["env"]
    return EnvConfig(**{k: tuple(v) if isinstance(v, list) else v for k, v in raw.items()})


def make(name: str, car: str, ckpt: str, preset: str, seed: int) -> tuple[dict, dict]:
    vp = load_vehicle(find_vehicle(car))
    track = segment_track(seed, preset, name=name)
    ck = ROOT / ckpt
    res = evaluate(load_policy(ck, "cpu"), vp, [track], "cpu", laps=3, cfg=env_cfg_of(ck), record=True)[0]
    if not res.finished:
        raise RuntimeError(f"{name}: the driver did not finish ({res.end_reason} at {res.distance_m:.0f} m)")
    laps = laps_from_result(res, track, vp.name, f"{ck.parent.name} (trained driver)", "learned",
                            "scripts/make_example_laps.py", ckpt)
    learned = min(laps, key=lambda l: l["meta"]["lap_time"])
    ref = reference_lap(track, vp)
    with tempfile.TemporaryDirectory() as tmp:
        p = Path(tmp) / "ref.npz"
        ref.save(p)
        reference = reference_lap_file(vp.name, track, p, vp.chassis.wheelbase_m, math.radians(vp.steering.max_wheel_angle_deg))
    for lap in (learned, reference):
        save_lap(lap, root=EXAMPLE_DIR)
    print(f"{name}: {car}  learned {learned['meta']['lap_time']:.3f} s  reference {reference['meta']['lap_time']:.3f} s"
          f"  (+{(learned['meta']['lap_time'] / reference['meta']['lap_time'] - 1) * 100:.1f} %)")
    return learned, reference


def render_gif(lap: dict, ghost: dict, out: Path, seconds: float = 14.0, speedup: float = 5.0, fps: int = 12) -> None:
    """An animated replay: track map with the racing line coloured by speed, the car and its ghost, a small HUD."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.animation import FuncAnimation, PillowWriter
    from matplotlib.collections import LineCollection

    s, g, tk = lap["samples"], ghost["samples"], lap["track"]
    t, x, y, v = map(np.asarray, (s["t"], s["x"], s["y"], s["speed"]))
    gt, gx, gy = map(np.asarray, (g["t"], g["x"], g["y"]))
    fig = plt.figure(figsize=(7.2, 4.6), dpi=90, facecolor="#14171c")
    ax = fig.add_axes([0.0, 0.0, 0.68, 1.0]); ax.set_facecolor("#14171c"); ax.set_aspect("equal"); ax.axis("off")
    hud = fig.add_axes([0.68, 0.0, 0.32, 1.0]); hud.axis("off"); hud.set_facecolor("#14171c")
    left, right = np.asarray(tk["left"]), np.asarray(tk["right"])
    for e in (left, right):
        ax.plot(*np.vstack([e, e[:1]]).T, color="#cfd5de", lw=0.8)
    pts = np.stack([x, y], 1)
    lc = LineCollection(np.stack([pts[:-1], pts[1:]], 1), cmap="turbo", array=v[:-1] * 3.6, lw=2.2)
    ax.add_collection(lc)
    ax.plot([left[0, 0], right[0, 0]], [left[0, 1], right[0, 1]], color="white", lw=2.5)
    ghost_dot, = ax.plot([], [], "o", ms=7, color="#a0aab9", mec="white")
    car_dot, = ax.plot([], [], "o", ms=9, color="#d5001c", mec="white", mew=1.5)
    m = lap["meta"]
    txt = dict(color="#e6e9ef", family="monospace")
    hud.text(0.05, 0.93, "Project MV", color="#d5001c", fontsize=15, weight="bold", transform=hud.transAxes)
    hud.text(0.05, 0.86, f"{m['car']}\n{m['track']} (generated)", color="#98a1b3", fontsize=8, transform=hud.transAxes)
    h_time = hud.text(0.05, 0.70, "", fontsize=17, transform=hud.transAxes, **txt)
    h_speed = hud.text(0.05, 0.56, "", fontsize=17, transform=hud.transAxes, **txt)
    h_gap = hud.text(0.05, 0.42, "", fontsize=13, transform=hud.transAxes, **txt)
    hud.text(0.05, 0.22, f"trained driver   {m['lap_time']:.3f} s\nphysics ideal    {ghost['meta']['lap_time']:.3f} s"
                         f"\n(grey dot = ideal lap)\nreplay {speedup:g}x speed", color="#98a1b3", fontsize=8.5,
             transform=hud.transAxes, family="monospace")
    gs = np.maximum.accumulate(np.asarray(g["s"]))
    ss = np.maximum.accumulate(np.asarray(s["s"]))
    n_frames = int(min(seconds, t[-1] / speedup) * fps)

    def update(k):
        tt = k / fps * speedup
        i = min(np.searchsorted(t, tt), len(t) - 1)
        j = min(np.searchsorted(gt, tt), len(gt) - 1)
        car_dot.set_data([x[i]], [y[i]]); ghost_dot.set_data([gx[j]], [gy[j]])
        gap = tt - np.interp(ss[i], gs, gt)
        h_time.set_text(f"{int(tt // 60)}:{tt % 60:06.3f}")
        h_speed.set_text(f"{v[i] * 3.6:5.0f} km/h")
        h_gap.set_text(f"gap to ideal {gap:+.2f} s")
        h_gap.set_color("#3fbf6f" if gap <= 0 else "#e05a55")
        return car_dot, ghost_dot, h_time, h_speed, h_gap

    out.parent.mkdir(parents=True, exist_ok=True)
    FuncAnimation(fig, update, frames=n_frames, blit=False).save(out, writer=PillowWriter(fps=fps))
    plt.close(fig)
    print(f"wrote {out} ({out.stat().st_size / 1e6:.1f} MB)")


def main() -> None:
    import torch
    torch.set_num_threads(4)
    made = [make(*e) for e in EXAMPLES]
    learned, reference = made[0]
    render_gif(learned, reference, ROOT / "docs" / "img" / "lap_replay.gif", seconds=16.0, speedup=1.5, fps=12)


if __name__ == "__main__":
    main()
